(()=>{const form=document.querySelector('#footerForm'),previews=[...document.querySelectorAll('.site-footer')],desktop=previews[0],mobile=previews[1],shell=document.querySelector('.review-shell'),lock=document.querySelector('#lockButton'),reset=document.querySelector('#resetButton'),output=document.querySelector('#selectionReadout'),key='mindmake-footer-combination-v1',defaults=Object.fromEntries(new FormData(form).entries()),labels={structureDesktop:'Desktop structure',structureMobile:'Mobile structure',densityDesktop:'Desktop density',densityMobile:'Mobile density',brand:'Brand treatment',statement:'Supporting sentence',routes:'Route grouping',legal:'Legal placement',copyright:'Copyright line',ground:'Footer ground',rule:'Top boundary',reveal:'Entrance'};const read=()=>Object.fromEntries(new FormData(form).entries());const apply=s=>{desktop.dataset.structureDesktop=s.structureDesktop;desktop.dataset.densityDesktop=s.densityDesktop;mobile.dataset.structureMobile=s.structureMobile;mobile.dataset.densityMobile=s.densityMobile;previews.forEach(p=>{p.dataset.brand=s.brand;p.dataset.statement=s.statement;p.dataset.routes=s.routes;p.dataset.legal=s.legal;p.dataset.copyright=s.copyright;p.dataset.ground=s.ground;p.dataset.rule=s.rule;p.dataset.reveal=s.reveal;p.querySelector('.footer-statement').textContent=s.statement==='short'?'Keep your edge as AI changes the market.':'We help leaders keep their edge as AI changes their market, and you keep what it learns.';p.querySelector('small').textContent=s.copyright==='short'?'© 2026 Mindmake.':'Copyright 2026 Mindmake. Built in public, used in private.';});};const restore=s=>{Object.entries(s).forEach(([n,v])=>{const t=form.elements.namedItem(n);if(t instanceof RadioNodeList)t.value=v;else if(t)t.value=v});apply(read())};const render=s=>{output.innerHTML=`<strong>Saved locally</strong><br>${Object.entries(labels).map(([k,l])=>`${l}: ${s[k]}`).join('<br>')}<br>Comment: ${s.comment?.trim()||'none'}`;lock.textContent='Combination locked';shell.classList.add('is-locked')};form.addEventListener('change',()=>{apply(read());shell.classList.remove('is-locked');lock.textContent='Lock this combination'});lock.addEventListener('click',()=>{const s=read();localStorage.setItem(key,JSON.stringify(s));const clean={...s};delete clean.comment;history.replaceState(null,'',`#${new URLSearchParams(clean)}`);render(s)});reset.addEventListener('click',()=>{localStorage.removeItem(key);history.replaceState(null,'',location.pathname+location.search);form.reset();restore(defaults);output.textContent='';shell.classList.remove('is-locked');lock.textContent='Lock this combination'});let saved=null;try{saved=JSON.parse(localStorage.getItem(key))}catch{saved=null}if(saved){restore(saved);render(saved)}else apply(defaults)})();
